if(window.location.hostname!=="vedic-traditions.github.io"&&window.location.hostname!=="localhost"){throw new Error("Access denied");}
const AppState={backgroundMusic:null,currentSound:null,isMuted:false,isFirstClick:true,activeChertogId:null,selectedDate:null,currentDate:new Date()};
const MONTH_NAMES=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
const DAYS_IN_MONTH=[31,28,31,30,31,30,31,31,30,31,30,31];
const CHERTOG_PERIODS=[{id:1,start:327,end:355},{id:2,start:356,end:20},{id:3,start:21,end:50},{id:4,start:51,end:79},{id:5,start:80,end:110},{id:6,start:111,end:141},{id:7,start:142,end:172},{id:8,start:173,end:203},{id:9,start:204,end:235},{id:10,start:236,end:265},{id:11,start:266,end:296},{id:12,start:297,end:326}];
function initAudio(){if(AppState.isFirstClick){AppState.isFirstClick=false;playBackgroundMusic();}}
function playBackgroundMusic(){if(AppState.isMuted)return;if(!AppState.backgroundMusic){AppState.backgroundMusic=new Audio('musik/Иггдрассиль.mp3');AppState.backgroundMusic.loop=true;AppState.backgroundMusic.volume=0.3;}
AppState.backgroundMusic.play().catch(()=>{});}
function stopBackgroundMusic(){if(AppState.backgroundMusic){AppState.backgroundMusic.pause();AppState.backgroundMusic.currentTime=0;AppState.backgroundMusic.src='';AppState.backgroundMusic.load();AppState.backgroundMusic=null;}}
function playSound(fileName){if(AppState.isMuted)return;stopCurrentSound();stopBackgroundMusic();AppState.currentSound=new Audio(`musik/${fileName}.mp3`);AppState.currentSound.volume=0.8;AppState.currentSound.play().catch(()=>{});AppState.currentSound.onended=()=>{AppState.currentSound=null;playBackgroundMusic();};}
function stopCurrentSound(){if(AppState.currentSound){AppState.currentSound.pause();AppState.currentSound.currentTime=0;AppState.currentSound.src='';AppState.currentSound.load();AppState.currentSound=null;}}
document.getElementById('muteBtn').addEventListener('click',(e)=>{e.stopPropagation();AppState.isMuted=!AppState.isMuted;const btn=document.getElementById('muteBtn');if(AppState.isMuted){btn.textContent='🔇 Звук выключен';stopBackgroundMusic();stopCurrentSound();}else{btn.textContent='🔊 Звук включен';if(!AppState.currentSound){playBackgroundMusic();}}});
document.addEventListener('click',initAudio,{once:true});
function initChertogs(){const leftColumn=document.getElementById('leftColumn');const rightColumn=document.getElementById('rightColumn');if(typeof chertogs==='undefined'||!Array.isArray(chertogs)||chertogs.length===0){setTimeout(initChertogs,500);return;}
chertogs.forEach((chertog,index)=>{const icon=document.createElement('div');icon.className='chertog-icon';icon.id=`chertog-${chertog.id}`;icon.onclick=()=>window.openModal('chertog',chertog.id);const imgPath=`chertogs/${chertog.fileName}.webp`;icon.innerHTML=`<img src="${imgPath}" alt="${chertog.name}" loading="lazy" onerror="this.style.border='2px solid red'"><span class="icon-label">${chertog.abode}</span>`;const targetColumn=index<6?leftColumn:rightColumn;targetColumn.appendChild(icon);});}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initChertogs);}else{initChertogs();}
function initCalendar(){const yearSelect=document.getElementById('yearSelect');const currentYear=new Date().getFullYear();for(let year=currentYear-100;year<=currentYear+50;year++){const option=document.createElement('option');option.value=year;option.textContent=year;if(year===currentYear)option.selected=true;yearSelect.appendChild(option);}
document.getElementById('monthSelect').value=AppState.currentDate.getMonth();window.renderCalendar();}
window.renderCalendar=function(){const year=parseInt(document.getElementById('yearSelect').value);const month=parseInt(document.getElementById('monthSelect').value);const grid=document.getElementById('calendarGrid');grid.innerHTML='';const firstDay=new Date(year,month,1);const lastDay=new Date(year,month+1,0);const daysInMonth=lastDay.getDate();const startingDay=(firstDay.getDay()+6)%7;const prevMonthLastDay=new Date(year,month,0).getDate();for(let i=startingDay-1;i>=0;i--){const dayDiv=createDayElement(prevMonthLastDay-i,'other-month');grid.appendChild(dayDiv);}
const today=new Date();for(let day=1;day<=daysInMonth;day++){const isToday=year===today.getFullYear()&&month===today.getMonth()&&day===today.getDate();const isSelected=AppState.selectedDate&&year===AppState.selectedDate.getFullYear()&&month===AppState.selectedDate.getMonth()&&day===AppState.selectedDate.getDate();const classes=isToday?['today']:[];if(isSelected)classes.push('selected');const dayDiv=createDayElement(day,...classes);dayDiv.onclick=()=>selectDate(year,month,day);grid.appendChild(dayDiv);}
const totalCells=Math.ceil((startingDay+daysInMonth)/7)*7;const remainingCells=totalCells-(startingDay+daysInMonth);for(let day=1;day<=remainingCells;day++){grid.appendChild(createDayElement(day,'other-month'));}};
function createDayElement(day,...classes){const dayDiv=document.createElement('div');dayDiv.className=['calendar-day',...classes].join(' ');dayDiv.textContent=day;return dayDiv;}
function selectDate(year,month,day){AppState.selectedDate=new Date(year,month,day);document.getElementById('dateInput').value=`${day} ${MONTH_NAMES[month]} ${year}`;window.renderCalendar();closeCalendar();}
window.toggleCalendar=function(){document.getElementById('calendarPopup').classList.toggle('active');};
function closeCalendar(){document.getElementById('calendarPopup').classList.remove('active');}
document.addEventListener('click',(event)=>{const wrapper=document.querySelector('.calendar-wrapper');const popup=document.getElementById('calendarPopup');if(popup.classList.contains('active')&&!wrapper.contains(event.target)){closeCalendar();}});
window.changeMonth=function(delta){const monthSelect=document.getElementById('monthSelect');const yearSelect=document.getElementById('yearSelect');let month=parseInt(monthSelect.value)+delta;let year=parseInt(yearSelect.value);if(month<0){month=11;year--;}else if(month>11){month=0;year++;}
monthSelect.value=month;yearSelect.value=year;window.renderCalendar();};
window.calculateFromCalendar=function(){if(!AppState.selectedDate){alert('Пожалуйста, выберите дату на календаре');return;}
const day=AppState.selectedDate.getDate();const month=AppState.selectedDate.getMonth()+1;const chertogId=determineChertog(day,month);activateChertog(chertogId);};
function determineChertog(day,month){let dayOfYear=day;for(let i=1;i<month;i++){dayOfYear+=DAYS_IN_MONTH[i-1];}
if(month>2&&isLeapYear(new Date().getFullYear())){dayOfYear++;}
for(const period of CHERTOG_PERIODS){if(period.start>period.end){if(dayOfYear>=period.start||dayOfYear<=period.end){return period.id;}}else if(dayOfYear>=period.start&&dayOfYear<=period.end){return period.id;}}
return 1;}
function isLeapYear(year){return(year%4===0&&year%100!==0)||(year%400===0);}
function activateChertog(chertogId){document.querySelectorAll('.chertog-icon').forEach(icon=>icon.classList.remove('active'));document.getElementById('thorIcon').classList.remove('active');const chertogElement=document.getElementById(`chertog-${chertogId}`);if(chertogElement){chertogElement.classList.add('active');if(window.innerWidth<=900){setTimeout(()=>{chertogElement.scrollIntoView({behavior:'smooth',block:'center',inline:'center'});},100);}}
const thorIcon=document.getElementById('thorIcon');thorIcon.classList.add('active');if(window.innerWidth<=900&&!chertogElement){setTimeout(()=>{thorIcon.scrollIntoView({behavior:'smooth',block:'center'});},100);}
AppState.activeChertogId=chertogId;const chertog=chertogs.find(c=>c.id===chertogId);if(chertog){document.getElementById('resultDisplay').innerHTML=`<div class="abode-name">Обитель ${chertog.abode}</div><div class="god-phrase">${chertog.phrase}</div>`;}}
window.openModal=function(type,chertogId=null){const modal=document.getElementById('modal');const title=document.getElementById('modalTitle');const description=document.getElementById('modalDescription');const russianNames={'Ullr':'Улль','Freyr':'Фрейр','Odin-Wisdom':'Один-Мудрец','Saga':'Сага','Odin-Warrior':'Один-Воин','Skadi':'Скади','Baldr':'Бальдр','Heimdallr':'Хеймдалль','Freyja':'Фрейя','Forseti':'Форсети','Njord':'Ньёрд','Vidarr':'Видар'};if(type==='thor'){title.textContent='Трудхейм - Обитель Тора';description.innerHTML=thorData.description.replace(/\n/g,'<br>');playSound(thorData.fileName);}else if(type==='chertog'&&chertogId){const chertog=chertogs.find(c=>c.id===chertogId);if(chertog){const russianName=russianNames[chertog.name]||chertog.name;title.textContent=`${chertog.abode} - Обитель ${chertog.name}`;description.innerHTML=chertog.description.replace(/\n/g,'<br>');playSound(chertog.fileName);}}
modal.classList.add('active');};
window.closeModal=function(){document.getElementById('modal').classList.remove('active');stopCurrentSound();if(!AppState.isMuted){playBackgroundMusic();}};
document.getElementById('modal').addEventListener('click',(e)=>{if(e.target.id==='modal'){window.closeModal();}});
document.addEventListener('keydown',(e)=>{if(e.key==='Escape'){window.closeModal();}});
initCalendar();
